-- inside the reschedule branch, before the update
if p_new_start < now() then
  raise exception 'Reprogramacion en el pasado no permitida';
end if;

select et.duration_minutes, et.business_id into v_duration, v_business
  from public.event_types et where et.id = v_booking.event_type_id;

if v_business <> v_booking.business_id then
  raise exception 'Inconsistencia tenant';
end if;

if p_duration_minutes <> v_duration then
  raise exception 'Duracion no permitida';
end if;

if not exists (
  select 1 from public.schedules s
  where s.business_id = v_booking.business_id
    and extract(isodow from p_new_start at time zone 'UTC')::int = s.day_of_week
    and (p_new_start at time zone 'UTC')::time >= s.start_time
    and (p_new_start at time zone 'UTC')::time < s.end_time
) then
  raise exception 'Horario fuera de disponibilidad';
end if;

if exists (
  select 1 from public.availability_exceptions x
  where x.business_id = v_booking.business_id
    and x.exception_date = (p_new_start at time zone 'UTC')::date
    and x.is_available = false
) then
  raise exception 'Fecha bloqueada';
end if;

